package com.internhub.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="audit_logs") public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="admin_user_id",nullable=false) private User admin; @Column(nullable=false,length=80) private String action; @Column(name="target_type",nullable=false,length=40) private String targetType; @Column(name="target_id") private Long targetId; @Column(length=500) private String details; @Column(nullable=false) private Instant createdAt; public Long getId(){return id;} public User getAdmin(){return admin;} public void setAdmin(User v){admin=v;} public String getAction(){return action;} public void setAction(String v){action=v;} public String getTargetType(){return targetType;} public void setTargetType(String v){targetType=v;} public Long getTargetId(){return targetId;} public void setTargetId(Long v){targetId=v;} public String getDetails(){return details;} public void setDetails(String v){details=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} }
